SELECT tenant_id, knowledge_space_id, data_source_id, revision, object_ordinal,
       platform_object_id, content_digest, byte_size, media_type, fresh_at
FROM knowledge_data.source_revision_object
WHERE tenant_id = #{tenantId}
  AND knowledge_space_id = #{knowledgeSpaceId}
  AND data_source_id = #{dataSourceId}
  AND revision = #{revision}
ORDER BY object_ordinal
